def predict(df, p):
    def solve_one(dose, times):
        times = np.asarray(times, float)
        kin = p['R0']*p['kout']
        def f(t, y):
            C = pk_conc(dose, t)
            return [kin*(1 + p['Smax']*C/(p['SC50']+C)) - p['kout']*y[0]]
        sol = solve_ivp(f, [0, times.max()], [p['R0']], t_eval=times, rtol=1e-8, atol=1e-10)
        return sol.y[0]
    return per_dose(df, solve_one)

